mapper.select:
SELECT qs.id AS questionSubmitId, q.id AS questionId, q.title AS questionTitle, u.name AS userName, qs.language AS language, qs.judge_status AS judgeStatus, qs.question_result AS questionResult, qs.create_time AS createTime FROM question_submit qs JOIN question q ON qs.question_id = q.id JOIN user u ON qs.user_id = u.id WHERE qs.is_deleted = 0 AND q.is_deleted = 0 AND u.is_deleted = 0 AND q.check_status = 1
AND qs.user_id = #{userId}
AND q.title LIKE CONCAT('%', #{title}, '%')
AND qs.question_id = #{questionId}
AND qs.language = #{language}
AND qs.question_result = #{questionResult}
ORDER BY qs.create_time DESC
